WITH cleaned AS (SELECT *, COALESCE(price, 0) price_filled, COALESCE(brand, 'OTHER') brand_filled FROM products WHERE supplier_id IS NOT NULL) SELECT id, product_name, price, cost, stock_qty, tags, supplier_id, price_filled, SUM(price) OVER (PARTITION BY YEAR(launch_date) ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_price, COUNT(price) OVER w_part category_count_price, MIN(cost) OVER (PARTITION BY supplier_id) supplier_id_min_cost, NTILE(10) OVER (PARTITION BY category ORDER BY cost, id) cost_bucket, RANK() OVER (ORDER BY price_filled DESC NULLS LAST) price_filled_rank FROM cleaned WINDOW w_part AS (PARTITION BY category);
